-- 0281 -- Fund analytics: an idempotency key on a generated report, so a repeated click or a retried request never issues a second report.
--
-- Forward-only, additive, idempotent. HAND-OVER ARTEFACT: NOT APPLIED anywhere. Apply AFTER 0261 and 0269.
--
-- WHY (release candidate, blocker B3). A report is generated by one web request that the hosting platform ends after 28 seconds. A person
-- who clicks twice, a screen that asks again while a large report is prepared in steps, or a client that retries after a dropped connection
-- must end with ONE issued report, not one per request. The screen sends a key that stays the same for one intended report. The server
-- stores the key with the report. The same key sent again by the same person returns the report already issued for it and never makes another.
--
-- TWO COLUMNS, BOTH NULLABLE. idempotency_key is the opaque key (16 to 64 letters, digits, underscore or hyphen). request_fingerprint is the
-- SHA-256 of the request (period and the sorted fund choice) so a key that is reused for a DIFFERENT request is refused instead of silently
-- returning an unrelated report. A report made without a key (an older client) has both empty and is never matched, exactly as before.
--
-- UNIQUENESS. One partial unique index per person and key. A second insert with the same key fails with a unique violation, which the
-- server answers with the report that won. Existing rows are untouched (both columns empty). The immutability guard of 0261 refuses
-- updates only, so adding columns and an index does not interact with it, and a stored report is still never edited.
--
-- ROLLBACK: drop the index uidx_nav2_reports_user_idempotency, then the constraint nav2_reports_idempotency_shape, then the two columns.

alter table nav2_fund_analytics_reports add column if not exists idempotency_key text;
alter table nav2_fund_analytics_reports add column if not exists request_fingerprint text;

do $do$
begin
  if not exists (
    select 1 from pg_constraint
     where conname = 'nav2_reports_idempotency_shape'
       and conrelid = 'public.nav2_fund_analytics_reports'::regclass
  ) then
    alter table nav2_fund_analytics_reports add constraint nav2_reports_idempotency_shape check (
      (idempotency_key is null and request_fingerprint is null)
      or (idempotency_key is not null and request_fingerprint is not null
          and idempotency_key ~ '^[A-Za-z0-9_-]{16,64}$' and request_fingerprint ~ '^[0-9a-f]{64}$')
    );
  end if;
end $do$;

create unique index if not exists uidx_nav2_reports_user_idempotency
  on nav2_fund_analytics_reports (user_id, idempotency_key)
  where idempotency_key is not null;
